const qso_flag_t *qso_flag_lookup_key(const char *key)
{
 size_t lo=0,hi=sizeof(aliases)/sizeof(*aliases);
 while(lo<hi){size_t mid=lo+(hi-lo)/2;int order=strcmp(key,aliases[mid].name);
  if(!order)return &qso_country_flags[aliases[mid].index];
  if(order<0)hi=mid;else lo=mid+1;
 }
 return NULL;
}
